  'portal.email.inviteBody': "{name}님, 안녕하세요.\n\n{company}의 {by}님이 {account} 관련 요청을 한곳에서 확인할 수 있도록 초대했습니다. 각 요청의 진행 상황을 확인하고, 새 요청을 만들고, 답변할 수 있습니다.\n\n아래 링크로 로그인할 수 있습니다. 링크는 7일 동안 한 번만 사용할 수 있으며, 이후에는 로그인 페이지에서 새 링크를 요청할 수 있습니다.",
