  "sso.test.why.bad_signature": "서명이 여기 저장된 내용과 맞지 않았습니다(공급자가 키나 인증서를 갱신했을 수 있습니다). SAML이면 새 인증서를 ‘IdP 서명 인증서’에 붙여넣고 저장하세요.",
  "sso.test.why.bad_token": "응답이 다른 앱용이었거나 만료되었습니다. ‘발급자(Issuer)’와 ‘클라이언트 ID’, 그리고 공급자의 시계가 정확한지 확인하세요.",
  "sso.test.why.idp_unreachable": "ID 공급자에 연결할 수 없었거나 공급자가 바빴습니다. 토큰과 키 주소를 확인하고, 맞다면 1분 정도 기다리세요.",
  'errors.sso_untested': "먼저 이 정보로 ID 공급자를 통한 로그인을 테스트하세요. 그 후 SSO를 필수로 할 수 있습니다.",
