  'demo.hub.hero.title': '투어를 시작하세요. 진짜 제품입니다.',
  'demo.hub.hero.lead': '모든 투어는 브라우저에서 돌아가는 실제 앱 위에서, 가상의 회사와 그 고객으로 진행됩니다. 설치할 것도, 어디로 보내지는 데이터도 없습니다. 언제든 투어를 벗어나 마음대로 둘러보세요.',
