  "perm.finance.view.hint": "연결된 회계 프로그램의 미수 잔액, 연체 청구서, 입금 내역을 각 고객 페이지에서 봅니다. 이 권한이 없으면 헬스 스코어 안에서 결제가 며칠 늦었는지만 보입니다.",
  'health.signal.payment': "제때 결제",
