  "fin.addHint": "읽기 전용: 미수 잔액, 연체 청구서, 입금 내역이 각 고객 페이지에 표시되며, 결제 지연을 헬스 스코어에 반영할 수 있습니다. 프로그램에는 아무것도 쓰지 않습니다.",
