  'fin.what.zohobooks': "Zoho Books의 고객, 청구서, 입금 내역(모든 Zoho 데이터 센터).",
  'fin.what.xero': "Xero의 고객, 매출 청구서, 입금 내역.",
  'fin.what.odoo': "Odoo Online, Odoo.sh 또는 자체 서버의 고객, 청구서, 입금 내역.",
  'fin.what.freee': "freee 회계의 거래처(取引先)와 매출 거래.",
  'fin.what.parasut': "Paraşüt의 고객, 매출 청구서, 입금 내역.",
  'fin.what.quickbooks': "QuickBooks Online의 고객, 청구서, 입금 내역.",
  'fin.what.finfile': "Logo, Mikro, Tally, SAP Business One 등 다른 프로그램: Excel 또는 CSV로 내보낸 파일을 올리세요.",
  'fin.steps.zohobooks': "Zoho Books 조직을 볼 수 있는 Zoho 계정으로 로그인하세요.\nCurahold가 연락처, 청구서, 입금 내역을 읽도록 허용하세요. 읽기 권한만 요청합니다.\n여기로 돌아와 첫 읽기를 시작하고 연결되지 않은 고객을 확인하세요.",
  'fin.steps.xero': "Xero에 로그인하고 연결할 조직을 선택하세요.\n연락처와 거래의 읽기 권한을 허용하세요. Curahold는 Xero의 어떤 것도 바꿀 수 없습니다.\n여기로 돌아와 첫 읽기를 시작하고 연결되지 않은 고객을 확인하세요.",
  'fin.steps.freee': "freee에 로그인하고 연결할 사업소(事業所)를 선택하세요.\n접근을 허용하세요. Curahold는 거래처와 매출 거래만 읽습니다.\n여기로 돌아와 첫 읽기를 시작하고 연결되지 않은 고객을 확인하세요.",
  'fin.steps.quickbooks': "Intuit에 로그인하고 연결할 QuickBooks 회사를 선택하세요.\n회계 데이터 접근을 허용하세요. Curahold는 고객, 청구서, 입금 내역만 읽습니다.\n여기로 돌아와 첫 읽기를 시작하고 연결되지 않은 고객을 확인하세요.",
  'fin.steps.odoo': "Odoo에서 프로필 → 환경설정 → 계정 보안을 열고 API 키를 만드세요.\nOdoo 주소와 로그인 이름을 적어 두세요. Odoo.sh나 자체 서버라면 데이터베이스 이름도 필요합니다.\n아래에 입력하세요. Odoo Online에서는 API 접근에 Custom 요금제가 필요합니다(Odoo 규정).",
  'fin.steps.parasut': "Paraşüt 지원팀에 회사의 API 접근을 요청하세요. client ID와 client secret을 보내 줍니다.\n회사 번호는 주소창의 uygulama.parasut.com/ 뒤에 있습니다.\nParaşüt 사용자의 이메일과 비밀번호와 함께 입력하세요. 비밀번호는 키를 받는 데 한 번만 쓰이며 저장되지 않습니다.",
  'fin.steps.finfile': "프로그램에서 고객, 청구서, 입금 내역을 Excel 또는 CSV로 내보내세요.\n템플릿의 열에 맞춰 넣으세요. 템플릿은 다음 화면에서 내려받을 수 있습니다.\n고객, 청구서, 입금 순서로 올리세요. 더 최신 수치가 필요하면 언제든 새 파일을 올리면 됩니다.",
  'support.field.odoo.url': "Odoo 주소",
  'support.field.odoo.database': "데이터베이스 이름",
  'support.field.odoo.login': "로그인(이메일)",
