  'demo.tour.move-in.3.body': "하위 작업, 댓글, 사용자 지정 필드, \"대기\" 연결도 함께 옵니다. 미리 실행해 보면 무엇이 들어오고 무엇이 안 들어오는지 알려 주며, 목록 40개가 부서 보드 몇 개로 합쳐집니다.",
  'demo.tour.team-load.title': "누구에게 여유가 있고 어느 고객이 기다리나",
  'demo.tour.team-load.blurb': "앞으로의 주를 사람별로, 그리고 고객마다 진행 중 작업, 요청, 티켓을 한 페이지에서.",
