  'demo.tour.team-load.2.title': "모든 고객을 한눈에",
  'demo.tour.team-load.2.body': "진행 중·지연 작업, 포털 요청, 아직 해결되지 않은 티켓을 바쁜 순으로 보여 줍니다. 고객을 클릭하면 페이지가 열립니다.",
