  "hooks.how.esign": "DocuSign에서: Settings → Connect → Add Configuration → Custom. 주소를 URL to publish에 붙여 넣고 JSON을 고른 뒤 Envelope Sent, Completed, Declined, Voided를 선택하고, 여기 입력한 키로 HMAC을 켜세요.",
